using System.Diagnostics;

public class Solution
{
  public int LongestValidParentheses(string s)
  {
    if (s.Length < 2)
    {
      return 0;
    }

    var best = 0;
    var balanced = new HashSet<int>[s.Length + 1];
    balanced[2] = [];

    for (var i = 0; i < s.Length - 1; i++)
    {
      if (s[i] == '(' && s[i+1] == ')')
      {
        balanced[2].Add(i);
        best = 2;
      }
    }

    for (var i = 4; i <= s.Length; i+=2)
    {
      balanced[i] = [];

      // Find balanced substrings of length i through "(" B(i-2) ")"
      foreach (var index in balanced[i - 2])
      {
        if (index > 0 && index+i-2 < s.Length && s[index - 1] == '(' && s[index+i-2] == ')')
        {
          balanced[i].Add(index - 1);
        }
      }

      // Find balanced substrings of length i through B(k) B(i-k)
      for (var k = 2; k <= i - 2; k+=2)
      {
        foreach (var index in balanced[k])
        {
          if (i - k >= 0 && balanced[i - k].Contains(index + k))
          {
            balanced[i].Add(index);
          }
        }
      }

      if (balanced[i].Count > 0)
      {
        best = i;
      }
    }

    return best;
  }

