    Debug.Assert(solution.LongestValidParentheses("(()") == 2);
    Debug.Assert(solution.LongestValidParentheses(")()())") == 4);
    Debug.Assert(solution.LongestValidParentheses("") == 0);
    Debug.Assert(solution.LongestValidParentheses("()()()()(((") == 8);
    Debug.Assert(solution.LongestValidParentheses(")))))))(((") == 0);
    Debug.Assert(solution.LongestValidParentheses("()()()()(()") == 8);
    Debug.Assert(solution.LongestValidParentheses("))))((()((") == 2);
    Debug.Assert(solution.LongestValidParentheses("()(()") == 2);
    Debug.Assert(solution.LongestValidParentheses("(()(((()") == 2);
